import sys

sys.setrecursionlimit(200000)

class Node:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None

def singlevalued(root):
    count = 0

    def dfs(node):
        nonlocal count
        if node is None:
            return True

        left_unival = dfs(node.left)
        right_unival = dfs(node.right)

        if left_unival and right_unival:
            if node.left and node.left.val != node.val:
                return False
            if node.right and node.right.val != node.val:
                return False
            count += 1
            return True
        return False

    dfs(root)
    return count

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        print(0)
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
    except StopIteration:
        print(0)
        return

    if n == 0:
        print(0)
        return

    nodes = {}

    def get_node(idx):
        if idx in nodes:
            return nodes[idx]
        node = Node(None)
        nodes[idx] = node
        return node

    root = None

    for i in range(n):
        idx = i
        val_str = next(iterator)
        left_idx_str = next(iterator)
        right_idx_str = next(iterator)

        node = get_node(idx)
        node.val = int(val_str)

        if left_idx_str != '-1':
            left_idx = int(left_idx_str)
            node.left = get_node(left_idx)

        if right_idx_str != '-1':
            right_idx = int(right_idx_str)
            node.right = get_node(right_idx)

        if i == 0:
            root = node

    result = singlevalued(root)
    print(result)

if __name__ == "__main__":
    main()
